; Game init
; $81ff-$8235

; Game init after the cold start. Builds the screen row tables, initialises the high-score table (JSR $9dcc) and installs the interrupts. Sets the SID envelopes. Sets player 1 ($1c), lender 1 for both players ($4f01, $4f11), joystick port 1 ($1d) and music on ($5f = 0). Then starts the attract sequence at $9fa0.
game_init
        jsr build_row_tables
        jsr init_hiscores
        jsr install_interrupts
        lda #$09                        ; Voices 1 and 2: attack 0, decay 9
        sta ATDCY1
        sta ATDCY2
        lda #$39                        ; Voice 3: attack 3, decay 9
        sta ATDCY3
        lda #$00                        ; No filter, sustain 0, release 0
        sta RESON
        sta SUREL1
        sta SUREL2
        sta SUREL3
        lda #$01
        sta current_player
        sta $4f01
        sta $4f11
        sta joy_port                    ; $1d = 1: joystick port 1
        lda #$00
        sta music_off
        jmp attract_loop
